	for _, root := range splitNonEmptyLines(runGitOutput(ctx, runner, repoDir, "rev-list", "--max-parents=0", "HEAD")) {
		stdout := runGitOutput(ctx, runner, repoDir, "show", "-s", "--format=%aI", root)
